package it.frociart.app;
import java.util.*;
import static it.frociart.app.FlowModel.*;
/** Standalone PHP functions/control flow, with source origins and bounded semantic support. */
final class FlowPhp {
 static FlowSourceText generate(FlowSource.Program program,String runtime){if(program==null||!program.canGenerate())throw new IllegalArgumentException("Correggi il diagramma prima di generare il codice.");if(runtime==null||runtime.trim().isEmpty())throw new IllegalArgumentException("Il supporto PHP è vuoto.");return new Writer(program).generate(runtime);}
 static String templateNumber(double value){return number(value);}
 static String literal(String text){if(text==null)return "null";StringBuilder b=new StringBuilder("\"");for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'||c=='\\'||c=='$')b.append('\\').append(c);else if(c>=32&&c<=126)b.append(c);else if(Character.isHighSurrogate(c)&&i+1<text.length()&&Character.isLowSurrogate(text.charAt(i+1)))b.append("\\u{").append(Integer.toHexString(Character.toCodePoint(c,text.charAt(++i)))).append('}');else if(Character.isSurrogate(c))b.append("\\x").append(hex(0xe0|(c>>12),2)).append("\\x").append(hex(0x80|((c>>6)&63),2)).append("\\x").append(hex(0x80|(c&63),2));else b.append("\\u{").append(Integer.toHexString(c)).append('}');}return b.append('"').toString();}
 static String text(String text){for(int i=0;i<text.length();i++)if(Character.isSurrogate(text.charAt(i))){if(Character.isHighSurrogate(text.charAt(i))&&i+1<text.length()&&Character.isLowSurrogate(text.charAt(i+1))){i++;continue;}List<String> units=new ArrayList<>();for(char c:text.toCharArray())units.add(Integer.toString(c));return "FcText::units(["+String.join(", ",units)+"])";}return "FcText::fromUtf8("+literal(text)+")";}
 static String comment(String text){return literal(text).replace("?>","?\\u{3e}");}
 static String hex(long value,int width){String s=Long.toHexString(value);StringBuilder b=new StringBuilder();for(int i=s.length();i<width;i++)b.append('0');return b.append(s).toString();}
 static String number(double value){if(value==0)return "0.0";String simple=FlowPython.templateNumber(value);if(simple.startsWith("_fc.real("))return "$fc->real(\""+hex(Double.doubleToRawLongBits(value),16)+"\")";return !simple.contains(".")&&!simple.contains("e")&&!simple.contains("E")?simple+".0":simple;}
 static String bool(boolean value){return value?"true":"false";}
 static String identifier(String source){StringBuilder b=new StringBuilder();for(char c:source.toCharArray())if(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='_')b.append(c);else b.append("_u").append(hex(c,4));String name=b.toString();if(name.isEmpty()||name.charAt(0)>='0'&&name.charAt(0)<='9')name="value_"+name;return name.startsWith("_fc")?"value_"+name:name;}
 static String unique(String seed,Set<String> used){String name=seed;int suffix=2;while(!used.add(name))name=seed+"_"+(suffix++);return name;}
 static final class Symbol {final String name,original;Symbol(String name,String original){this.name=name;this.original=original;}}
 static final class CaseMap<T> extends LinkedHashMap<String,T>{String key(Object key){return ((String)key).toLowerCase(Locale.ROOT);}public T put(String key,T value){return super.put(key(key),value);}public T get(Object key){return super.get(key(key));}public boolean containsKey(Object key){return super.containsKey(key(key));}}
 static final class Writer {
  final FlowSource.Program program;final FlowSourceText.Builder output;final Map<String,String> functions=new HashMap<>();final Set<String> globals=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
  Map<String,Symbol> names;List<Symbol> symbols;FlowSource.Scope scope;final boolean references;int temporary;
  Writer(FlowSource.Program p){program=p;boolean refs=false;for(FlowSource.Scope s:p.scopes)for(FlowSource.Parameter parameter:s.parameters)refs|=parameter.byReference;references=refs;output=new FlowSourceText.Builder(p,"php");globals.addAll(Arrays.asList("main fc this GLOBALS _SERVER _GET _POST _FILES _COOKIE _SESSION _REQUEST _ENV __construct __destruct".split(" ")));for(FlowSource.Scope s:p.scopes)if(s.id!=null)functions.put(s.id,unique("flow_"+identifier(s.name),globals));}
  void line(String code){line(code,0,null);}void line(String code,int indent){line(code,indent,null);}void line(String code,int indent,FlowSource.Block block){output.addLine(code,indent,block==null?new FlowSourceText.Origin[0]:new FlowSourceText.Origin[]{new FlowSourceText.Origin(scope.id,block.id)});}
  FlowSourceText generate(String runtime){line("<?php");line("// Generato con Frociart — autore del software: mamt104");line("// Progetto: "+comment(program.title));line("// PHP 8.2+, CLI a 64 bit. Salva Programma.php ed esegui php Programma.php.");line("// Il programma non richiede Frociart o estensioni aggiuntive.");line("");line("final class Programma {");line("public function __construct(private FcRuntime $fc) {}",1);for(FlowSource.Scope s:program.scopes)writeScope(s);line("}");line("");line("// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---");String body=runtime.replace("\r\n","\n").replace('\r','\n');if(!body.startsWith("<?php\n"))throw new IllegalArgumentException("Il supporto PHP non contiene l'intestazione prevista.");body=body.substring(6);for(String value:body.split("\n",-1))line(value);line("");line("if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) {");line("$runtime = new FcRuntime();",1);line("$program = new Programma($runtime);",1);line("exit($runtime->run([$program, 'main']) ? 0 : 1);",1);line("}");return output.build();}
  void add(String name,Set<String> used){if(name!=null&&!names.containsKey(name)){Symbol s=new Symbol(unique(identifier(name),used),name);names.put(name,s);symbols.add(s);}}
  void collect(FlowSource.Expression e,Set<String> used){if(e==null)return;if(e.kind==FlowSource.ExpressionKind.Variable)add(e.text,used);for(FlowSource.Expression c:e.children)collect(c,used);}
  FlowSource.Parameter parameterFor(String name){for(FlowSource.Parameter p:scope.parameters)if(p.name.toLowerCase(Locale.ROOT).equals(name.toLowerCase(Locale.ROOT)))return p;return null;}
  void writeScope(FlowSource.Scope s){scope=s;for(FlowSource.Block n:s.notes)line("// Annotazione: "+comment(n.text),1,n);for(FlowSource.Block n:s.blocks)if(n.comment!=null&&!n.comment.isEmpty())line("// Nota ("+(s.blocks.indexOf(n)+1)+"): "+comment(n.comment),1,n);temporary=0;names=new CaseMap<>();symbols=new ArrayList<>();Set<String> used=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);used.addAll(globals);
   for(FlowSource.Parameter p:s.parameters)add(p.name,used);for(FlowSource.Block n:s.blocks){FlowSource.Operation o=n.operation;if(o.input!=null){add(o.input.name,used);collect(o.input.index,used);}if(o.declaration!=null){for(String name:o.declaration.names)add(name,used);collect(o.declaration.size,used);}for(FlowSource.Write w:o.writes){add(w.target.name,used);collect(w.target.index,used);collect(w.value,used);}collect(o.value,used);}
   List<String> args=new ArrayList<>(),parameters=new ArrayList<>();for(FlowSource.Parameter p:s.parameters){args.add("$"+names.get(p.name).name);parameters.add(literal(names.get(p.name).original)+" => $"+names.get(p.name).name);}
   line("public function "+(s.id==null?"main":functions.get(s.id))+"("+String.join(", ",args)+") {",1);line("$fc = $this->fc;",2);line("$fc->guardCall();",2);for(FlowSource.Parameter p:s.parameters)line(p.byReference?"$fc->checkReference($"+names.get(p.name).name+", "+p.type+");":"$fc->checkType($"+names.get(p.name).name+", "+p.type+", "+bool(p.isArray)+");",2);line("$fc->enter("+literal(s.id==null?null:s.name)+", ["+String.join(", ",parameters)+"]"+(references?", true":"")+");",2);line("$_fc_types = [];",2);line("$_fc_error = null;",2);
   for(Symbol sym:symbols)if(parameterFor(sym.original)==null)line("$"+sym.name+" = $fc->unset;",2);line("try {",2);line("$fc->checkMemory();",3);FlowSourcePlan plan=FlowSourcePlan.create(s);if(plan.structured)writeStatements(plan.statements,3);else writeExplicit(3);line("} catch (\\Throwable $_fc_caught) {",2);line("$_fc_error = $_fc_caught;",3);line("throw $_fc_caught;",3);line("} finally {",2);line("$fc->leave($_fc_error);",3);line("}",2);line("}",1);for(FlowSource.Block n:s.blocks)if(!n.reachable){line("");line("// Blocco non raggiungibile, escluso dall'esecuzione: "+comment(n.text),1,n);}line("");
  }
  String name(String original,Map<String,String> staged){if(references)return "$fc->lookup("+literal(names.get(original).original)+")";String value=staged!=null&&staged.containsKey(original)?staged.get(original):"$"+names.get(original).name;return "$fc->value("+value+", "+literal(names.get(original).original)+")";}
  boolean callsFunction(FlowSource.Expression e){if(e==null)return false;if(e.functionId!=null)return true;for(FlowSource.Expression c:e.children)if(callsFunction(c))return true;return false;}
  FlowSource.Scope callee(String id){if(id!=null)for(FlowSource.Scope s:program.scopes)if(id.equals(s.id))return s;return null;}
  String expression(FlowSource.Expression e,int indent,FlowSource.Block block){return expression(e,indent,block,null,0,false);}String expression(FlowSource.Expression e,int indent,FlowSource.Block block,Map<String,String> staged){return expression(e,indent,block,staged,0,false);}
  String expression(FlowSource.Expression e,int indent,FlowSource.Block block,Map<String,String> staged,int depth,boolean track){if(e==null)return "null";if(depth==0)track=track||callsFunction(e);
   if(depth>=24){String helper="$_fc_expr_"+(++temporary);List<String> captures=new ArrayList<>(Arrays.asList("$fc","&$_fc_types"));for(Symbol symbol:symbols)captures.add("&$"+symbol.name);if(staged!=null)for(String value:new LinkedHashSet<>(staged.values()))captures.add("&"+value);line(helper+" = function() use ("+String.join(", ",captures)+") {",indent,block);String value=expression(e,indent+1,block,staged,0,track);line("return "+value+";",indent+1,block);line("};",indent,block);return helper+"()";}
   int key=track?++temporary:0;String result;switch(e.kind){case Number:return number(e.number);case Text:return "$fc->text("+text(e.text)+")";case Boolean:return bool(e.bool);case Variable:return name(e.text,staged);default:break;}
   FlowSource.Scope called=callee(e.functionId);List<String> children=new ArrayList<>();for(int i=0;i<e.children.size();i++){FlowSource.Expression c=e.children.get(i);boolean ref=called!=null&&called.parameters.get(i).byReference;String child=ref?"$fc->hold("+key+", $fc->reference("+literal(names.get(c.text).original)+", "+declaration(c.text)+", "+parameter(c.text)+"))":expression(c,indent,block,staged,depth+1,track);children.add(track&&!ref?"$fc->hold("+key+", "+child+")":child);}
   switch(e.kind){case Vector:result="$fc->vector(["+String.join(", ",children)+"])";break;case Index:result=references&&e.children.get(0).kind==FlowSource.ExpressionKind.Variable?"$fc->atName("+literal(names.get(e.children.get(0).text).original)+", fn() => "+children.get(1)+")":"$fc->at("+children.get(0)+", fn() => "+children.get(1)+")";break;case Unary:String value=children.get(0);result=e.text.equals("not")?"(!$fc->truth("+value+"))":e.text.equals("-")?"(-$fc->number("+value+"))":"$fc->number("+value+")";break;
    case Call:String args=String.join(", ",children);if(e.functionId!=null)return "$fc->call("+key+", [$this, "+literal(functions.get(e.functionId))+"]"+(args.isEmpty()?"":", "+args)+")";result="$fc->intrinsic("+literal(e.text)+(args.isEmpty()?"":", "+args)+")";break;
    case Binary:String a=children.get(0),b=children.get(1),op=e.text;if(op.equals("and")||op.equals("or"))result="($fc->truth("+a+") "+(op.equals("and")?"&&":"||")+" $fc->truth("+b+"))";else if(op.equals("=")||op.equals("=="))result="$fc->equal("+a+", "+b+")";else if(op.equals("!=")||op.equals("<>"))result="(!$fc->equal("+a+", "+b+"))";else if(Arrays.asList("<","<=",">",">=").contains(op))result="$fc->compare("+a+", "+b+", "+literal(op)+")";else{String method=op.equals("&")?"concat":op.equals("+")?"add":op.equals("-")?"sub":op.equals("*")?"mul":op.equals("/")?"div":op.equals("%")?"mod":"power";result="$fc->"+method+"("+a+", "+b+")";}break;
    default:throw new IllegalArgumentException("Espressione PHP non supportata.");
   }return track&&!e.children.isEmpty()?"$fc->release("+key+", "+result+")":result;
  }
  String test(FlowSource.Block n,int indent){return "$fc->test(fn() => "+expression(n.operation.value,indent,n)+")";}
  void writeStatements(List<FlowSourcePlan.Statement> statements,int indent){for(FlowSourcePlan.Statement s:statements){if(s.kind==FlowSourcePlan.Kind.Instruction){writeInstruction(s.block,indent);continue;}if(s.kind==FlowSourcePlan.Kind.Repeat){line("while (true) {",indent,s.entryBlock());writeBody(s.body,indent+1,s.block);line("if ("+(s.loopOnTrue?"!":"")+test(s.block,indent+1)+") break;",indent+1,s.block);line("}",indent,s.block);continue;}String condition=test(s.block,indent);if(s.kind==FlowSourcePlan.Kind.While){line("while ("+(s.loopOnTrue?"":"!")+condition+") {",indent,s.block);writeBody(s.body,indent+1,s.block);line("}",indent,s.block);}else{line("if ("+condition+") {",indent,s.block);writeBody(s.body,indent+1,s.block);line("} else {",indent,s.block);writeBody(s.otherwise,indent+1,s.block);line("}",indent,s.block);}}}
  void writeBody(List<FlowSourcePlan.Statement> body,int indent,FlowSource.Block owner){if(body.isEmpty())line("// Nessuna operazione.",indent,owner);else writeStatements(body,indent);}
  void writeExplicit(int indent){line("// Collegamenti espliciti per conservare questo grafo.",indent);line("$_fc_block = "+literal(scope.startId)+";",indent);line("while (true) {",indent);line("switch (true) {",indent+1);for(FlowSource.Block n:scope.blocks){line("case $_fc_block === "+literal(n.id)+":",indent+2,n);if(n.kind==DECISION){line("if ("+test(n,indent+3)+") {",indent+3,n);line("$_fc_block = "+literal(n.next("true"))+";",indent+4,n);line("} else {",indent+3,n);line("$_fc_block = "+literal(n.next("false"))+";",indent+4,n);line("}",indent+3,n);}else{writeInstruction(n,indent+3);if(n.kind!=END)line("$_fc_block = "+literal(n.next("next"))+";",indent+3,n);}line("break;",indent+3,n);}line("default:",indent+2);line("throw new FcError('Collegamento non valido nel sorgente modificato.');",indent+3);line("}",indent+1);line("}",indent);}
  String declaration(String name){return "($_fc_types["+literal(names.get(name).name)+"] ?? null)";}
  String parameter(String name){FlowSource.Parameter p=parameterFor(name);return p==null?"null":"["+p.type+", "+bool(p.isArray)+"]";}
  String convert(String value,String name){return "$fc->convert("+value+", "+declaration(name)+", "+parameter(name)+")";}
  void writeInstruction(FlowSource.Block n,int indent){FlowSource.Operation o=n.operation;line(n.kind==INPUT?"$fc->guard();":"$fc->step();",indent,n);if(n.kind==START||n.kind==PAUSE)return;
   if(n.kind==END){if(scope.id==null){line("$fc->finishFiles();",indent,n);line("return;",indent,n);}else if(scope.returnType==VOID)line("return;",indent,n);else line("return $fc->checkType("+expression(o.value,indent,n)+", "+scope.returnType+", "+bool(scope.returnIsArray)+");",indent,n);return;}
   if(n.kind==PROCESS){line("$fc->beginValues();",indent,n);Map<String,String> staged=new CaseMap<>();List<String> order=new ArrayList<>(),temps=new ArrayList<>();for(FlowSource.Write w:o.writes){String value=expression(w.value,indent,n,staged);if(w.target.index!=null){String index=expression(w.target.index,indent,n,staged);value=references?"$fc->setAfterName("+value+", "+literal(names.get(w.target.name).original)+", fn() => "+index+")":"$fc->setAfter("+value+", "+name(w.target.name,staged)+", fn() => "+index+")";}value="$fc->stage("+literal(names.get(w.target.name).original)+", "+convert(value,w.target.name)+(references&&w.target.index!=null?", true, true":"")+")";if(o.writes.size()==1){line("$"+names.get(w.target.name).name+" = "+value+";",indent,n);continue;}String temp="$_fc_tmp_"+(++temporary);temps.add(temp);line(temp+" = "+value+";",indent,n);if(!staged.containsKey(w.target.name))order.add(w.target.name);staged.put(w.target.name,temp);}if(o.writes.size()>1){for(String name:order)line("$"+names.get(name).name+" = "+staged.get(name)+";",indent,n);for(String temp:temps)line(temp+" = null;",indent,n);}line("$fc->commit();",indent,n);return;}
   if(n.kind==DECLARE){FlowSource.Declaration d=o.declaration;String size=d.isArray()?expression(d.size,indent,n):"0.0",temp="$_fc_size_"+(++temporary);line(temp+" = $fc->integer("+size+", 0, 1024, 'La dimensione');",indent,n);line("$fc->beginValues();",indent,n);List<String> values=new ArrayList<>();for(String name:d.names){String value="$_fc_tmp_"+(++temporary);values.add(value);line(value+" = $fc->stage("+literal(names.get(name).original)+", $fc->initial("+d.type+", "+bool(d.isArray())+", "+temp+"), false);",indent,n);}line("$fc->commit(true);",indent,n);for(int i=0;i<d.names.size();i++){String name=d.names.get(i);line("$"+names.get(name).name+" = "+values.get(i)+";",indent,n);line("$_fc_types["+literal(names.get(name).name)+"] = ["+d.type+", "+bool(d.isArray())+", "+temp+"];",indent,n);}for(String value:values)line(value+" = null;",indent,n);return;}
   if(n.kind==INPUT||n.kind==READ_FILE){FlowSource.Target target=o.input;String suffix=declaration(target.name)+", "+parameter(target.name);if(target.index!=null)suffix+=", "+name(target.name,null)+", fn() => "+expression(target.index,indent,n);String read=n.kind==INPUT?"$fc->read("+literal(names.get(target.name).original)+", "+literal(n.prompt==null?"":n.prompt)+", "+suffix+")":"$fc->readFile("+literal(names.get(target.name).original)+", "+suffix+")";line("$"+names.get(target.name).name+" = "+read+";",indent,n);if(n.kind==INPUT)line("$fc->step();",indent,n);return;}
   if(n.kind==OPEN_FILE)line("$fc->requireClosed("+bool(o.fileReading)+");",indent,n);if(n.kind==WRITE_FILE)line("$fc->requireWrite();",indent,n);String e=expression(o.value,indent,n),code;
   switch(n.kind){case OUTPUT:code="$fc->emit("+e+(o.outputNewline?"":", false")+")";break;case CALL:code=e;break;case OPEN_FILE:code="$fc->openFile("+bool(o.fileReading)+", "+e+")";break;case WRITE_FILE:code="$fc->writeFile("+e+", "+bool(o.fileNewline)+")";break;case CLOSE_FILE:code="$fc->closeFile("+bool(o.fileReading)+")";break;case TURTLE_FORWARD:code="$fc->turtleForward("+e+", "+bool(o.turtleDraw)+")";break;case TURTLE_TURN:code="$fc->turtleTurn("+e+", "+bool(o.turtleLeft)+")";break;case TURTLE_HOME:code="$fc->turtleHome()";break;case TURTLE_CLEAR:code="$fc->turtleClear()";break;case TURTLE_PEN:code="$fc->turtlePen("+e+")";break;default:throw new IllegalArgumentException("Blocco PHP non supportato.");}line(code+";",indent,n);
  }
 }
}
